    for lineno, ln in lines[1:]:
        fields = [f.strip() for f in next(csv.reader([ln]))]
        if len(fields) != len(COLUMNS):
            raise FormatError(f"expected {len(COLUMNS)} fields, found {len(fields)}", source, lineno)
